<?php
$trip=trip_by_id((int)($_SESSION['trip_id']??0));$seats=$_SESSION['chosen_seats']??[];if(!$trip||!$seats){echo '<section class="container content-section"><div class="empty-state"><h2>Choose your train and seats first</h2><a class="button primary" href="?page=search">Search journeys</a></div></section>';return;}
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$name=trim((string)($_POST['name']??''));$email=filter_var(trim((string)($_POST['email']??'')),FILTER_VALIDATE_EMAIL);$phone=trim((string)($_POST['phone']??''));$concession=in_array($_POST['concession']??'adult',['adult','student','senior'],true)?$_POST['concession']:'adult';if(mb_strlen($name)<2||mb_strlen($name)>100||!$email||!preg_match('/^[0-9+() -]{7,20}$/',$phone)){flash('Please check your name, email and phone number.','error');}else{try{$pdo=db();$pdo->beginTransaction();$codes=$seats;$ins=$pdo->prepare("UPDATE trip_seats SET status='reserved' WHERE trip_id=? AND status='available' AND seat_code=?");foreach($codes as $code){$ins->execute([$trip['id'],$code]);if($ins->rowCount()!==1)throw new RuntimeException('Seat availability changed. Please choose seats again.');}$fare=fare_for($trip,$concession,count($codes));$ref=booking_ref();$b=$pdo->prepare("INSERT INTO bookings(reference,trip_id,email,phone,total_fare,status,concession,created_at) VALUES(?,?,?,?,?,'confirmed',?,NOW())");$b->execute([$ref,$trip['id'],$email,$phone,$fare,$concession]);$bid=(int)$pdo->lastInsertId();$p=$pdo->prepare('INSERT INTO passengers(booking_id,full_name,email,phone) VALUES(?,?,?,?)');$p->execute([$bid,$name,$email,$phone]);$bs=$pdo->prepare('INSERT INTO booking_seats(booking_id,trip_seat_id,seat_code) VALUES(?,?,?)');$find=$pdo->prepare('SELECT id FROM trip_seats WHERE trip_id=? AND seat_code=?');foreach($codes as $code){$find->execute([$trip['id'],$code]);$bs->execute([$bid,$find->fetchColumn(),$code]);}$pdo->prepare('INSERT INTO booking_events(booking_id,event_type,note,created_at) VALUES(?,?,?,NOW())')->execute([$bid,'booked','Demo reservation confirmed; payment simulated']);$pdo->commit();$_SESSION['booking_email']=$email;$_SESSION['booking_id']=$bid;$_SESSION['booking_ref']=$ref;unset($_SESSION['trip_id'],$_SESSION['chosen_seats']);header('Location: ?page=confirmation');exit;}catch(Throwable $e){if(isset($pdo)&&$pdo->inTransaction())$pdo->rollBack();flash($e instanceof RuntimeException?$e->getMessage():'Booking could not be saved. Check the database and try again.','error');}}}
$total=fare_for($trip,'adult',count($seats));
?>
<section class="page-banner"><div class="container"><p class="eyebrow">STEP 2 OF 3 · PASSENGER</p><h1>Almost <em>there.</em></h1><p>Enter the lead passenger details for this reservation.</p></div></section><section class="container content-section"><div class="form-layout"><form class="form-card" method="post"><?= csrf_field() ?><p class="eyebrow">LEAD PASSENGER</p><h2>Who’s travelling?</h2><p class="muted">Your booking reference and ticket will be shown after confirmation.</p><label>Full name<input name="name" maxlength="100" autocomplete="name" required placeholder="Name as shown on ID"></label><div class="form-row"><label>Email address<input type="email" name="email" maxlength="190" autocomplete="email" required placeholder="you@example.com"></label><label>Phone number<input type="tel" name="phone" maxlength="20" pattern="[0-9+() -]{7,20}" autocomplete="tel" required placeholder="+60 12 345 6789"></label></div><label>Fare type<select name="concession"><option value="adult">Adult · full fare</option><option value="student">Student · 15% demo discount</option><option value="senior">Senior · 20% demo discount</option></select></label><div class="demo-notice"><strong>Demo payment</strong><span>No real payment will be collected. This booking flow confirms a sample reservation.</span></div><button class="button primary full-width">Confirm sample booking <span>→</span></button></form><aside class="journey-summary"><p class="eyebrow">YOUR SELECTION</p><h3><?= h($trip['origin']) ?> <span>→</span> <?= h($trip['destination']) ?></h3><p><?= h($trip['train_code']) ?> · <?= h(date('D, d M Y',strtotime($trip['depart_at']))) ?></p><div class="summary-line"><span>Seats</span><strong><?= h(implode(', ',$seats)) ?></strong></div><div class="summary-line"><span>Base fare</span><strong><?= money((float)$trip['base_fare']) ?> × <?= count($seats) ?></strong></div><div class="summary-line total-line"><span>From</span><strong><?= money($total) ?></strong></div><small>Final total reflects the fare type selected.</small></aside></div></section>
